CREATE TABLE IF NOT EXISTS users(telegram_id BIGINT PRIMARY KEY,username TEXT,first_name TEXT,last_name TEXT,points BIGINT NOT NULL DEFAULT 0 CHECK(points>=0),ad_credits BIGINT NOT NULL DEFAULT 0,referrer_id BIGINT REFERENCES users(telegram_id),membership_verified BOOLEAN NOT NULL DEFAULT FALSE,is_blocked BOOLEAN NOT NULL DEFAULT FALSE,is_admin BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ DEFAULT NOW(),last_active_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS transactions(id BIGSERIAL PRIMARY KEY,telegram_id BIGINT REFERENCES users(telegram_id),type TEXT NOT NULL,points_change BIGINT NOT NULL,balance_after BIGINT NOT NULL,description TEXT,reference TEXT UNIQUE,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS tasks(id BIGSERIAL PRIMARY KEY,type TEXT CHECK(type IN('channel','bot','website')),title TEXT NOT NULL,description TEXT,link TEXT NOT NULL,reward BIGINT NOT NULL,target INTEGER DEFAULT 0,completed INTEGER DEFAULT 0,active BOOLEAN DEFAULT TRUE,telegram_channel TEXT,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS task_completions(id BIGSERIAL PRIMARY KEY,task_id BIGINT REFERENCES tasks(id),telegram_id BIGINT REFERENCES users(telegram_id),reward BIGINT,created_at TIMESTAMPTZ DEFAULT NOW(),UNIQUE(task_id,telegram_id));
CREATE TABLE IF NOT EXISTS daily_claims(telegram_id BIGINT REFERENCES users(telegram_id),claim_date DATE,reward BIGINT,PRIMARY KEY(telegram_id,claim_date));
CREATE TABLE IF NOT EXISTS deposits(id BIGSERIAL PRIMARY KEY,telegram_id BIGINT REFERENCES users(telegram_id),tx_hash TEXT UNIQUE,amount_usdt NUMERIC(24,8),status TEXT DEFAULT 'pending',created_at TIMESTAMPTZ DEFAULT NOW(),reviewed_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS withdrawals(id BIGSERIAL PRIMARY KEY,telegram_id BIGINT REFERENCES users(telegram_id),amount_usdt NUMERIC(24,8),fee_usdt NUMERIC(24,8),net_usdt NUMERIC(24,8),wallet_address TEXT,status TEXT DEFAULT 'pending',tx_hash TEXT,created_at TIMESTAMPTZ DEFAULT NOW(),reviewed_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS referral_events(id BIGSERIAL PRIMARY KEY,referrer_id BIGINT REFERENCES users(telegram_id),referred_id BIGINT UNIQUE REFERENCES users(telegram_id),qualified_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS campaigns(id BIGSERIAL PRIMARY KEY,owner_id BIGINT REFERENCES users(telegram_id),type TEXT,title TEXT,link TEXT,reward BIGINT,target INTEGER,completed INTEGER DEFAULT 0,status TEXT DEFAULT 'pending',created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value JSONB NOT NULL);
